import{_ as e,o as a,c as n,X as i}from"./chunks/framework.CNGPadWr.js";const u=JSON.parse('{"title":"Installation","titleTemplate":":title · PyCellPack","description":"","frontmatter":{},"headers":[],"relativePath":"python/docs/installation.md","filePath":"python/docs/installation.md"}'),s={name:"python/docs/installation.md"};function o(d,t,r,l,c,p){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Use the <code>pycellpack</code> distribution and import package. From a repository checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/CellPack</span></span></code></pre></div><p>This installs from source through maturin and requires a compatible Rust toolchain and native build environment. Use an authorized build worker where compilation is restricted. An already built wheel can be installed through <code>uv add /path/to/wheel.whl</code>.</p><h2 id="dependencies-and-integrations" tabindex="-1">Dependencies and integrations <a class="header-anchor" href="#dependencies-and-integrations" aria-label="Permalink to &quot;Dependencies and integrations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Dependencies</th></tr></thead><tbody><tr><td>Core package</td><td>Python, NumPy and typing-extensions, as declared in <code>pyproject.toml</code></td></tr><tr><td>SciPy conveniences</td><td>The <code>scipy</code> extra</td></tr><tr><td>AnnData / H5AD / H5CP</td><td>The <code>anndata</code> extra and its declared Python-version constraints</td></tr><tr><td>Training Tensor batches</td><td>Install PyTorch separately for the target environment</td></tr><tr><td>Native process/access functions</td><td>A compatible native compiler or a prepared shared library; Numba where used</td></tr></tbody></table><p>The current package declares Python <code>&gt;=3.10,&lt;3.16</code>. The AnnData extra is pinned separately and requires Python 3.12 or newer. Importing <code>pycellpack</code> does not import SciPy, AnnData, h5py, pandas, PyTorch, or Numba; integrations load dependencies when used.</p><p>For an existing project, select the needed extras when adding the checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/absolute/path/to/CellPack[scipy,anndata]&#39;</span></span></code></pre></div><p>Continue with the <a href="/cellpack-docs/python/docs/quickstart.html">matrix quickstart</a> or <a href="/cellpack-docs/python/training/">training examples</a>.</p>',10)])])}const k=e(s,[["render",o]]);export{u as __pageData,k as default};
